5	const SPHINX = "sphinx";
6	const SPHINX_BASE_SCORE = 2;
7	const MAX_TYPES_SCORING_THE_BASE = 3;
8	const SCORE_AT_THE_THRESHOLD = 1;
9	const SCORE_PER_EXTRA_TYPE = 2;
10	
11	const isSphinx = (card: Card): boolean => card.monster === SPHINX;
12	
13	const countOtherMonsterTypes = (army: Card[], scoringIndex: number): number =>
14	  new Set(
15	    army.filter((_, index) => index !== scoringIndex).map((card) => card.monster),
16	  ).size;
17	
18	const scoreOneSphinx = (army: Card[], scoringIndex: number): number => {
19	  const otherTypeCount = countOtherMonsterTypes(army, scoringIndex);
20	  if (otherTypeCount <= MAX_TYPES_SCORING_THE_BASE) return SPHINX_BASE_SCORE;
21	
22	  const extraTypes = otherTypeCount - MAX_TYPES_SCORING_THE_BASE;
23	  return SCORE_AT_THE_THRESHOLD + SCORE_PER_EXTRA_TYPE * extraTypes;
24	};
25	
26	export const scoreArmy = (army: Card[]): number =>
27	  army.reduce(
28	    (total, card, index) =>
29	      isSphinx(card) ? total + scoreOneSphinx(army, index) : total,
30	    0,
31	  );
